/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «هكذا نربّي!» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["nrbi"]={"id":"nrbi","title":"هكذا نربّي!","sub":"50 معياراً لتربية المراهق، 5 مهارات لرفع كفاءة الوالدين وفعاليتهما","author":"د. مصطفى أبو سعد","coauthors":[],"translator":"","publisher":"شركة الإبداع الفكري للنشر والتوزيع، الكويت","year":"2011","edition":"الأولى","series":"","lead":"دليل تربوي مصور يقدم للوالدين خمسين معيارا لبناء أسرة تربوية فعالة مع المراهق، ثم خمس مهارات عملية لرفع كفاءتهما في الإنصات والاختيار والتفهم والتكاتف واللمسة الأبوية. ويقول مؤلفه في خلاصته: «هكذا نربي... قدّم للقارئ محاولة جديدة لتشكيل ثقافة تربوية مبنية على المعايير والقيم والمهارات والمعرفة...»","audience":"الآباء والمربون والمرشدون التربويون المتعاملون مع المراهقين","bio":"استشاري نفسي وتربوي. دكتوراه في علم النفس التربوي. ماجستير في الإرشاد النفسي (علم النفس العيادي).","chapters":[{"k":"c1","t":"منطلقات: المراهقة والأسرة","q":"كيف نفهم المراهق ومراحل نموه، وما أنماط الآباء والأسر التي تصنعه؟","essence":"افهم المراهق قبل أن تربيه","kw":["مراحل المراهقة","التناقض","أنواع الأسر"],"sections":[{"t":"منطلقات","pg":8,"key":"إنَّ هدف التربية الأساس هو أن تجعل المتربي إنساناً ناضجاً حرّاً مسؤولاً، وأهلاً لاتخاذ القرارات.","p":["فللطفل منذ الولادة شخصية تتطلب النمو، فهو ليس كما يدّعي بعضهم صفحة بيضاء أكتب عليها ما أشاء، ولا عجينة أشكّلها كما أشاء.","للتعرف بفاعلية على أبنائنا في سن المراهقة ينبغي نسيان (كيف كنا في سنهم)."],"items":[{"h":"مكونات الشخصية","x":"يجعلها الكتاب ثلاثة: الحاجات الإنسانية، والتواصل الاجتماعي مع المحيط، والقيم العليا."},{"h":"خطر الحاجات غير المشبعة","x":"«إن لم يشبع المراهق حاجاته، أو أشبعها بطرائق غير مشروعة ومخالفة لنظام القيم السائد في مجتمعه، فإنه يتعرض لمشكلات كبيرة تتعلق بالتطرف السلوكي في أدائه اليومي...» (ص 11)"}]},{"t":"اختر من يكون ابنك","pg":12,"key":"من يترك أثرا إيجابيا يذكر به وينفع الله به الناس...","p":["إن لم تضف شيئاً على الحياة كنت أنت الزائد عليها."],"items":[{"h":"صاحب بصمة","x":"إنسان يترك أثرا إيجابيا يذكر به وينفع الله به الناس."},{"h":"إنسان عادي","x":"يعيش حياته دون أثر مميز."},{"h":"الإنسان الصفر","x":"«من يأتون للحياة من باب الحياة... وينشؤون ويعيشون بسرداب طيلة عمرهم... ثم يودعون الحياة من باب الموت... ولم يكونوا شيئا مذكورا..» (ص 13)"}]},{"t":"مراهقة بلا مشكلات","pg":14,"key":"التربية فهم قبل أن تكون ممارسة... ابذل جهدك لفهم مراحل المراهقة","p":["طالما أكدنا أن العصا لم تنزل من الجنة، وأن الوسائل العقابية تدمر أكثر مما تصلح..","اجعلوا أبناءكم يعجبون بسلوككم الراقي في المعاملة... فيحبونكم.. ثم يقلدونكم.. ويومها فقط لن يقلدوا غيركم..."],"items":[{"h":"مراحل الفتى","x":"مرحلة التقليد (من 12 إلى 15)، ثم مرحلة الاعتزاز بالنفس (بعد 15)، ثم مرحلة الاتزان الاجتماعي في نهاية المرحلة."},{"h":"مراحل الفتاة","x":"ما قبل المراهقة، ثم الاضطراب (من 13 إلى 15)، ثم التقليد (من 15 إلى 16)، ثم الاتزان."},{"h":"المطلوب تربويا","x":"يقترح الكتاب العمل التطوعي والصحبة الصالحة سبيلا لإشباع حاجات المراهق."}]},{"t":"المراهق ومرحلة التناقض","pg":22,"key":"أفضل حل لهذه التناقضات التي يمر بها المراهق هو إشعار الابن أنه محبوب بالرغم من... (أي خطأ أو ممارسة تصدر منه)..","p":["يقع المراهق في حيرة شديدة بين حبه لوالديه والتمرد عليهما."],"items":[{"h":"تسعة تناقضات","x":"يعرض الكتاب تسعة تناقضات يعيشها المراهق، أولها الحب أو التمرد، وثانيها الاعتمادية والاستقلال."},{"h":"الخطوة 1","x":"«أوصل لابنك أنه يظل محبوبا بالرغم من أي شيء؛ لأن الحب فطرة..» (ص 34)"},{"h":"الخطوة 2","x":"«ابن علاقة حب وصداقة مع ابنك، وعامله كصديق (صاحبوهم)..» (ص 34)"},{"h":"الخطوة 4","x":"«تفهّم أن الصراع ليس حتميا وملامحه ستطفو بقوة... ومهما كان يمكن حله بسهولة.. بل ويمكن تجنبه..» (ص 35)"},{"h":"الخطوة 6","x":"«ضع حدودا وضوابط معقولة على سلوكهم.» (ص 35)"},{"h":"صرخات الأبناء","x":"من شكاوى الأبناء التي يرصدها الكتاب: «لم أعد صغيرا..» و«إني أختنق من كثرة نصائحكما..» (ص 36)"}]},{"t":"نماذج من الآباء وأساليب السيطرة","pg":42,"key":"يريد تحقيق الانضباط لكنه واقعي فيما يتوقعه.","p":["من الآباء من يعتقد أن السيطرة على المراهقين هو الحل في التعامل معهم وضبطهم والتحكم في حياتهم وضمان عدم انحرافهم.. وهو اعتقاد خطأ"],"items":[{"h":"الأب الحازم","x":"يضع القواعد ويفرضها على أبنائه، وهو «حساس لحاجة أبنائه ومتجاوب معهم.» (ص 42)"},{"h":"الأب المتسلط","x":"«يكثر من الأوامر والنواهي.» و«غير حسّاس لاحتياجات أبنائه، ولا يتفهمها.» (ص 43)"},{"h":"الأب المتساهل","x":"«لا يطلب من الأبناء إلا أقل القليل.» و«عندما يتطرف في تلبية احتياجات أبنائه يجعلهم أبناء مدللين.» (ص 44)"},{"h":"الأب الذي لا يبالي","x":"«يقضي معظم أوقاته منشغلاً عنهم في أعمال أخرى.» (ص 45)"},{"h":"استجابات الأبناء للسيطرة","x":"إما تقبل ظاهري للسيطرة مع خضوع واستسلام، وإما رفض وتمرد وعناد (ص 202 و203)."},{"h":"10 أساليب خاطئة","x":"منها الضبط المستمر والمتابعة الدائمة، والمنع التام، وحرمان الابن من المال، والابتزاز العاطفي، والمن عليه، والإغداق المبالغ فيه بالهدايا (ص 205 إلى 207)."}]},{"t":"أنواع الأسر ونماذج المراهقين","pg":46,"key":"ولكن البيت الشوري لا يبيح لتلك الخلافات أن تدوم وتعشعش فيه فترات طويلة من الزمن، بل يعالجها ويزيلها بالمناقشة الصريحة، وبروح التعاون والصداقة.","p":["هناك أدلة كثيرة على أن المراهقين الذين يسرف آباؤهم في المحافظة عليهم؛ يصعب عليهم جداً النجاح في مستقبل حياتهم."],"items":[{"h":"الأسرة النابذة","x":"«وهي الأسرة التي يكون فيها الابن منبوذاً وغير مرغوب فيه من الأب أو من كليهما...» (ص 46)"},{"h":"الأسرة القابلة","x":"ينشأ فيها المراهق محبوبا مقبولا، والأبوان فيها نشآ غالبا في بيوت يسودها الحب والعطف (ص 49)."},{"h":"الأسرة المستبدة","x":"«قد يهتم الأبوان بالابن ويحبانه، ولكنهما يجعلانه مضطراً إلى خضوع دائم تقريباً؛ لأنهما يعتقدان أن ذلك من مصلحته.» (ص 50)"},{"h":"الأسرة المسرفة في المحافظة","x":"ينشأ فيها المراهق ناقص الثقة بالنفس، يميل إلى الخجل، ويتهرب من المسؤولية (ص 54)."},{"h":"الأسرة الشورية","x":"«في الأسرة الشورية يتعلم الأفراد أدب الاختلاف» (ص 57)"},{"h":"أربعة نماذج من المراهقين","x":"كاتم المشكلات، والمجاهر بالمشكلات، والهارب من المشكلات، والمواجه للمشكلات، وهو أفضلها (ص 58 إلى 61)."}]}],"quiz":[{"q":"ما الهدف الأساس للتربية كما يحدده الكتاب في منطلقاته؟","o":["أن يصبح المتربي ناضجا حرا مسؤولا أهلا للقرار","أن يطيع المتربي والديه طاعة تامة بلا أي نقاش أبدا","أن يتفوق المتربي في دراسته على جميع أقرانه","أن يكتب المربي على الطفل ما يشاء من القيم"],"why":"إنَّ هدف التربية الأساس هو أن تجعل المتربي إنساناً ناضجاً حرّاً مسؤولاً، وأهلاً لاتخاذ القرارات.","pg":8},{"q":"ابن في مرحلة التقليد يقلد أصدقاءه في كل شيء. ما الطريق الذي يقترحه الكتاب ليقلد أباه بدلا منهم؟","o":["أن يعجب بسلوك أبيه الراقي فيحبه ثم يقلده","أن يعاقبه أبوه كلما قلد أحدا من أصدقائه","أن يتركه يقلد من يشاء دون أي توجيه منه","أن يعزله عن أصدقائه حتى تنتهي المرحلة"],"why":"اجعلوا أبناءكم يعجبون بسلوككم الراقي في المعاملة... فيحبونكم.. ثم يقلدونكم.. ويومها فقط لن يقلدوا غيركم...","pg":15},{"q":"أي نماذج الآباء يضع القواعد ويفرضها، وهو في الوقت نفسه حساس لحاجات أبنائه؟","o":["نموذج الأب الحازم","نموذج الأب المتسلط","نموذج الأب المتساهل","نموذج الأب غير المبالي"],"why":"حساس لحاجة أبنائه ومتجاوب معهم.","pg":42},{"q":"بم يتميز المراهق المواجه للمشكلات عن غيره من النماذج؟","o":["يتحدث عن مشكلته مع من يثق بهم ويكرر المحاولة","يكتم مشكلته ويعيش مع أحلام اليقظة ليحلها","يجاهر بالعناد والعدوانية ليكسب قبول الشلة التي يتبعها","يهرب من البيت ليلفت انتباه أهله إلى قيمته"],"why":"وهو أفضل الأنواع؛ لأنه يواجه المشكلة ولا يكتمها أو يهرب منها بل يتحدث عنها مع زملائه، أو مع بعض البالغين ممن يثق فيهم","pg":61},{"q":"ما أفضل حل لتناقضات المراهق بين الحب والتمرد بحسب الكتاب؟","o":["إشعاره أنه محبوب بالرغم من أي خطأ يصدر منه","مراقبته الدائمة حتى تنتهي مرحلة التناقض","تركه وحده حتى يحسم تناقضاته بنفسه دون تدخل من أحد","تذكيره دائما بما كان عليه والداه في سنه"],"why":"أفضل حل لهذه التناقضات التي يمر بها المراهق هو إشعار الابن أنه محبوب بالرغم من... (أي خطأ أو ممارسة تصدر منه)..","pg":33}],"scene":{"t":"لم أعد صغيرا","x":"ابنك ذو الخمسة عشر عاما يصرخ في وجهك بعد نقاش حاد: لم أعد صغيرا، أختنق من كثرة نصائحك. ماذا تفعل؟","opts":["تؤكد له أنه محبوب مهما حدث، وتعامله صديقا، وتضع حدودا معقولة","تذكره بأنه ما زال صغيرا وأن عليه أن يطيع دون نقاش","تتركه يفعل ما يريد تجنبا لأي صراع معه"],"why":"أوصل لابنك أنه يظل محبوبا بالرغم من أي شيء؛ لأن الحب فطرة..","pg":34}},{"k":"c2","t":"حوار مع أبنائي المراهقين","q":"ما متطلبات الحوار الإيجابي مع المراهق ومعاييره؟","essence":"حوار يقنع ولا يفرض","kw":["الحوار","الحب غير المشروط","الثقة"],"sections":[{"t":"4 متطلبات لبناء حوار إيجابي مع المراهقين","pg":62,"key":"يبدأ العمل الجاد في تربية أبنائنا وبناء علاقة إيجابية من خلال الحوار... فلا خير في أسرة لا تحاور أبناءها...","p":["أما صمت المراهق لبعض الوقت فيجب احترامه، وعدم إجباره على الحديث؛ فهو يحتاج أحياناً لأن يخلو إلى نفسه."],"items":[{"h":"انفتاح","x":"«يستطيع الأب اللبق أن يتحدث عن بعض ما صادفه في يومه من صعوبات أو طرائف، فيشجع الأبناء على التحدث عن مواقف مماثلة صادفتهم.» (ص 62)"},{"h":"وقت لأبنائي","x":"«أما الاعتذار بأنه لا يوجد وقت لذلك فهو عذر يجب تلافيه لصالح الأبناء ولصالح الأسرة.» (ص 62)"},{"h":"الإنصات","x":"صد الابن حين يتحدث عن شيء يراه الأب تافها يجعل الأبناء يحجمون عن الحديث بعد ذلك (ص 63)."},{"h":"احترام صمته","x":"لا يجبر المراهق على الحديث، فهو يحتاج أحيانا إلى الخلوة بنفسه (ص 63)."}]},{"t":"22 معيارا: الإقناع والتقبل والكرامة","pg":64,"key":"لا تدفع ابنك لأن يفكر ويؤمن بما تريده، أو بما ترى أنه الأنسب؛ فهذا قد يدفعه للتمرد، أو للتصديق بلا نقاش.","p":["لكن هذا التقبل أو التصديق المفروض سرعان ما يتحول إلى عناد أيضاً."],"items":[{"h":"1. أقنعه بما تريد","x":"الإقناع بديل الفرض، لأن التصديق المفروض يتحول إلى عناد."},{"h":"2. تقبل أسئلتهم","x":"«بل نناقشهم بهدوء، ونقدم لهم كتباً يقرؤونها في هذا الموضوع، ونتابعهم حتى يقتنعوا ويؤمنوا.» (ص 65)"},{"h":"3. سلوكيات تقطع حبل التواصل","x":"«إن التشدد والصرامة من جانب الآباء قد يقطعان حبل التواصل» (ص 65)"},{"h":"4. سلوكيات تدفع للانحراف","x":"«فكان الانحراف نتيجة حتمية لانعدام لغة التفاهم.» (ص 66)"},{"h":"5. تعرّف على ابنك بعمق","x":"«لذلك لا تتخذ أي موقف تجاه ولدك قبل أن تتحرى الحقيقة الكاملة.» (ص 66)"},{"h":"6. تعرّف على مكونات شخصيته","x":"«ركز على إبراز محاسن شخصية ابنك، وعززها بالدعم والمدح.» (ص 67)"},{"h":"7. احفظ كرامته","x":"«تذكّر أن هدف التربية الأساس حفظ الكرامة.» (ص 67)"}]},{"t":"الحب والطاعة والحزم","pg":68,"key":"الحب غير المشروط ضروري لنضج شخصية الأبناء.","p":["الطاعة لا تعني الموافقة على طول الخط، أو عدم الرد أو المناقشة عند تلقي الأوامر. بل الطاعة تكون نتيجة الحب."],"items":[{"h":"8. الحب الإيجابي","x":"«وهناك حب هدام مثل الإفراط في الحماية مما يدمر شخصية الأبناء.» (ص 68)"},{"h":"9. حب بلا شروط","x":"قول الأب «إن كنت مطيعاً سأحبك» «يجعل الابن يحس أنه مرفوض إذا فعل عكس ذلك.» (ص 68)"},{"h":"10. حب متبادل","x":"«فنحن نؤدّبهم لأننا نحبهم.» (ص 69)"},{"h":"11. طاعة إيجابية","x":"«فالابن (أو الابنة) ينفذ ما يطلب إليه لأنه يحب والديه.» (ص 69)"},{"h":"12. حزم وحب","x":"«لكن المحبة تشتمل على نوع من الحزم.» وهو حزم دون عنف (ص 70)."},{"h":"13. قوانين للتنفيذ","x":"«لا تفرض قوانين أسرية لن تستطيع الحفاظ على تنفيذها.» (ص 70)"},{"h":"14. ثقة وحسن ظن","x":"«لتكن الثقة أساس التعامل دائماً وليس الشك.» (ص 71)"},{"h":"15. تشجيع على المصارحة","x":"«فيتعود الابن الذي يخطئ أن يعترف بأخطائه، حتى قبل أن يكتشف الأهل هذا الخطأ.» (ص 72)"}]},{"t":"المسؤولية والقيم والعدل","pg":73,"key":"أما عدم إعطاء أية مسؤولية بدعوى الإشفاق فهو مضر بالأبناء؛ لأنه يؤثر في شخصياتهم، إذ يُنشئون شخصيات تعتمد على غيرها دائماً.","p":["أخيراً.. لا يوجد ابن كامل؛ كما لا يوجد أب كامل. توقع الخطأ من ابنك ولا تنتظر منه الكمال"],"items":[{"h":"16. تدريب على المسؤولية","x":"مسؤولية تناسب سن الابن وخبرته، وإشراكه في الرأي عند قرارات الأسرة (ص 73)."},{"h":"17. مهارة حل المشكلات","x":"«لا تتبين موقف ابنك وتسانده بل دعه يتحمل مسؤولية قراراته» (ص 74)"},{"h":"18. اهتمام متزن بمكونات الشخصية","x":"«فالحياة لا تحتاج إلى التفوق الدراسي فقط بقدر ما تحتاج إلى نضج اجتماعي ووعي.» (ص 75)"},{"h":"19. قيم ثابتة","x":"«القيم قضية تربوية غير قابلة للتنازل» (ص 76)"},{"h":"20. مساواة في المعاملة","x":"«فلا نفضل الكبير على الصغير، ولا الولد على البنت.» (ص 76)"},{"h":"21. ذكاءات وقدرات مختلفة","x":"«والشخصيات كما نعرف مثل بصمات الأصابع لا توجد شخصيتان متطابقتان تماماً.» (ص 77)"},{"h":"22. عدل ومعاملة","x":"«ولنحذر دائماً من التفريق في المعاملة بين الأولاد والبنات» (ص 78)"}]}],"quiz":[{"q":"ابن يطرح أسئلة تشكك في بعض العقائد الأساسية. ما موقف الكتاب من ذلك؟","o":["يناقشه أبوه بهدوء ويقدم له كتبا ويتابعه حتى يقتنع","ينهره أبوه بشدة حتى لا يعود إلى مثل هذه الأسئلة أبدا","يتجاهل أبوه أسئلته لأنها مرحلة عابرة ستنتهي","يمنعه أبوه من القراءة في هذا الموضوع منعا تاما"],"why":"بل نناقشهم بهدوء، ونقدم لهم كتباً يقرؤونها في هذا الموضوع، ونتابعهم حتى يقتنعوا ويؤمنوا.","pg":65},{"q":"ما المقصود بالطاعة الإيجابية في معايير الحوار؟","o":["طاعة تنبع من حب الابن لوالديه لا من الخوف","موافقة الابن على أوامر والديه على طول الخط","تنفيذ الأوامر دون رد أو مناقشة عند تلقيها","طاعة يكافأ عليها الابن بالهدايا والوعود"],"why":"الطاعة لا تعني الموافقة على طول الخط، أو عدم الرد أو المناقشة عند تلقي الأوامر. بل الطاعة تكون نتيجة الحب.","pg":69},{"q":"ما الأثر السلبي لقول الأب لابنه: إن كنت مطيعا سأحبك؟","o":["يشعر الابن أنه مرفوض إذا فعل عكس ذلك","يجعل الابن مدللا لا يطلب منه إلا القليل","يدفع الابن إلى الاعتراف بأخطائه مبكرا","يقطع حبل التواصل بسبب كثرة النصائح"],"why":"أما القول: \"إن تصرفت بالطريقة التي أريدها سأحبك\" أو \"إن كنت مطيعاً سأحبك\" فإنه يجعل الابن يحس أنه مرفوض إذا فعل عكس ذلك.","pg":68},{"q":"كيف يصف الكتاب الابن الذي لا يخطئ لأنه يخاف من والديه؟","o":["شخص غير مسؤول ومعرض للخطأ دائما","شخص منضبط يستحق الثقة الكاملة","شخص ناضج تجاوز مرحلة التناقض","شخص قوي الإرادة يعتمد على نفسه"],"why":"فالابن (الابنة) الذي لا يخطئ لأنه يخاف من والديه شخص غير مسؤول، ومعرض للخطأ دائماً.","pg":71},{"q":"أب يهتم بدرجات ابنه وحدها ويمنعه من الرحلات والأنشطة. أي معيار خالفه؟","o":["الاهتمام المتزن بمكونات الشخصية","المساواة في المعاملة بين الأبناء","القيم الثابتة التي لا تقبل التنازل","تشجيع الابن على المصارحة التامة"],"why":"من أكبر الأخطاء أن يركز الآباء على التقدم الدراسي فقط دون الاهتمام بتقدم الأبناء خلقيا وروحيا ونفسيا ووجدانيا وفكريا واجتماعيا أو رياضيا","pg":75}],"scene":{"t":"اعتراف بعد خطأ","x":"كسر ابنك تحفة ثمينة في البيت دون قصد، ثم جاء يعترف لك بخطئه قبل أن تكتشفه. ماذا تفعل؟","opts":["تقدر اعترافه وتحمله مسؤولية بسيطة دون قسوة","تعاقبه بشدة حتى يكون أكثر حرصا في المرة القادمة","تتجاهل الأمر كليا حتى لا تجرح مشاعره"],"why":"فيتعود الابن الذي يخطئ أن يعترف بأخطائه، حتى قبل أن يكتشف الأهل هذا الخطأ.","pg":72},"rel":[{"b":"teen","ci":5,"t":"التعامل مع مشكلات المراهقين"},{"b":"lebon","ci":6,"t":"الكتاب الرابع: مسألة التربية"}]},{"k":"c3","t":"معايير بناء أسرة تربوية فعالة: 50 معيارا","q":"ما المعايير التي تبني بيئة أسرية إيجابية فعالة مع المراهق؟","essence":"خمسون معيارا لبيت تربوي آمن","kw":["القدوة","ضبط الانفعال","المدح"],"sections":[{"t":"العلاقات الأسرية","pg":80,"key":"يتلخص سر السعادة في الحياة الأسرية في كلمة واحدة هي: المحبة؛ فالأسرة المتحابة التي يحب كل فرد فيها باقي الأفراد حبا حقيقيا تتمتع بحياة سليمة نفسيا واجتماعيا.","p":["المعايير الخمسون التي أدرجها هنا هي خلاصة دراسات تربوية علمية وأكاديمية شكلت أساسا علميا وخلفية نظرية فضلاً عن تجاربي الشخصية وممارساتي المهنية ومتابعاتي في عالم الإرشاد التربوي والنفسي.."],"items":[{"h":"رؤية المؤلف","x":"«التربية على المبادئ والالتزام بالمعايير والقيم أهم وأجدى من التربية على السلوك» (ص 108)"},{"h":"الشخصية قبل الطاعة","x":"«بناء الشخصية الإيجابية من أولويات التربية الفعالة.. وهي مقدّمة على إرغام الأولاد على الطاعة» (ص 101)"}]},{"t":"المعايير 1 إلى 10: المربي القدوة وبيئة الأمن","pg":85,"key":"لا تقل في بيتي مراهق ولكن قل: أكرمني الله بمراهق هدية لي..","p":["تعلّم أن تقول «آسف» إذا اعتقدت أنك أخطأت، وصحّح موقفك دون خشية أن تهتز صورتك أمام أبنائك.."],"items":[{"h":"المعيار 1: لا للأحكام الجاهزة","x":"«الأحكام الجاهزة والقوالب النمطية تعد من أسوأ أعداء البيئة التربوية الفعالة والإيجابية.» (ص 85)"},{"h":"المعيار 2: المثل الأعلى","x":"«إعطاء المثل الأعلى في السلوك والخلق يعد دوما أساسا تربويا في العلاقة مع المراهقين...» (ص 85)"},{"h":"المعيار 3: كن مربيا راقيا","x":"«احرص دوما أن تكون راقيا ومربيا إيجابيا واعتن بنفسك لتكون كذلك..» ولا تكن قاضيا ولا محققا ولا سجانا. (ص 86)"},{"h":"المعيار 4: اجتناب صراع الوالدين","x":"«اجتناب الصراعات بين الوالدين ولا سيما أمام الأولاد..» و«تعلّم أن تقول «آسف» إذا اعتقدت أنك أخطأت» (ص 86)"},{"h":"المعيار 5: منبع الأمن","x":"«الوالدان ينبغي أن يكونا دوما منبعا للأمن..» (ص 87)"},{"h":"المعيار 6: فرص المسؤولية","x":"«البيئة التي تتيح الفرص لتحمل المسؤولية تسهم إسهاما كبيراً على تقوية الشخصية لدى المراهقين..» (ص 87)"},{"h":"المعيار 7: توقع ردود أفعالهم","x":"«لاحظ أسلوبك وتحكّم في كلماتك فإنها تصنع شخصيات أبنائك..» (ص 88)"},{"h":"المعيار 8: راجع سلوكك","x":"«لاحظ باستمرار سلوكك مع أبنائك، واحرص على أن تكون إيجابيا وفعالا، وتراجع عن السلبي منه وما لا فائدة منه..» (ص 88)"},{"h":"المعيار 9: صديق في التجربة نفسها","x":"«التحدث مع صديق لك له أبناء في سن أبنائك يعد دوما أمرا مفيدا..» (ص 89)"},{"h":"المعيار 10: مهارات حل الخلافات","x":"«علّم أبناءك مهارات حل الخلافات وإدارة الصراعات، وابحث معهم على الحلول المناسبة وتعلموها معا...» (ص 89)"}]},{"t":"المعايير 11 إلى 20: الإنصات وضبط الانفعال","pg":89,"key":"الإنصات يمكن أن يكون فعالا للغاية وأكثر فائدة من الحديث..","p":["الصراخ من خوارم الوقار والمروءة لا أحد يعجب بشخص يصرخ.."],"items":[{"h":"المعيار 11: الإنصات","x":"«أنصت لأبنائك في الصغر ينصتون لك في الكبر...» (ص 89)"},{"h":"المعيار 12: حوارات عامة","x":"«20 دقيقة حوار يومي تجعل منك صديقا عزيزا في حياة أبنائك..» (ص 90)"},{"h":"المعيار 13: الهدوء قبل الحوار","x":"«في حالة التوتر والغضب يتحول المربي إلى آلة للقمع وإصدار الأوامر والنواهي...» (ص 90)"},{"h":"المعيار 14: لا تتدخل في كل شيء","x":"«ليس كل شيء في حياة أبنائنا ينبغي التدخل فيه..» (ص 91)"},{"h":"المعيار 15: لا للسخرية","x":"«لا تسخر من ابنك فقد تتحول كلمات السخرية إلى اعتقادات ثم سلوكيات ثم اضطرابات...» (ص 92)"},{"h":"المعيار 16: لا للصراخ","x":"«الصراخ كارثة تربوية ومدمرة للشخصية ولا فائدة تتحقق منه..» (ص 93)"},{"h":"المعيار 17: قل لا بهدوء","x":"«يمكنك دوما قول (لا).. تعلّم كيف تقولها دون صراخ أو غضب أو عنف..» (ص 93)"},{"h":"المعيار 18: ضبط الانفعالات","x":"«لا تفقد هدوءك، واحرص على ضبط انفعالاتك..» (ص 94)"},{"h":"المعيار 19: أوامر قليلة","x":"«إصدار أوامر قليلة لا تقبل التفاوض يشعر الجميع بالأمن.. ويحافظ على رقي التعايش وسلامة الحياة الأسرية...» (ص 94)"},{"h":"المعيار 20: لست آلة أوامر","x":"«احرص على ألا تكون آلة مستمرة العمل في إصدار الأوامر.. والنواهي..» (ص 95)"}]},{"t":"المعايير 21 إلى 30: الكلمة والثقة والاستقلال","pg":95,"key":"لا تهن أبناءك بتهديدات مستمرة بعقوبات تعرف مسبقا أنها لا تؤتي أكلها ولا فائدة ترجى منها...","p":["اضمن لأبنائك استقلاليتهم، وامنحهم حق الاختيار ودربهم على قوته.."],"items":[{"h":"المعيار 21: لا للتهديد","x":"«التهديد أسلوب سلبي يحطم المعنويات ويدمر العلاقات...» (ص 95)"},{"h":"المعيار 22: الاستقلالية","x":"«إذا أردت أن ينشأ أبناؤك كالصقور؛ فعلمهم أن يحلقوا عاليا ولوحدهم..» (ص 96)"},{"h":"المعيار 23: رسائل (أنت)","x":"«أبناؤنا تصنعهم كلماتنا ونعوتنا من خلال رسائل (أنت) ومن خلال طريقة تقديمهم للآخرين..» (ص 97)"},{"h":"المعيار 24: عين النحلة","x":"«ضبط الأولاد وهم يخطئون وفضحهم لا فائدة منه.. الأفضل أن تبتسم وترفع المعنويات من خلال ضبطهم وهم يحسنون..» (ص 97)"},{"h":"المعيار 25: لا تعلم أبناءك الكذب","x":"«السلوكيات السلبية من تهديد وعقاب وغيره قد تدفع الأبناء للكذب..» (ص 98)"},{"h":"المعيار 26: الاحترام","x":"«لا تقبل أبدا أن يتصرف الأبناء بسلوك يخدش احترام أحد..» (ص 98)"},{"h":"المعيار 27: المذكرات اليومية","x":"«تدريب الأولاد وتشجيعهم على كتابة مذكراتهم اليومية ولاسيما مذكرات النجاحات والأحداث المهمة تساعدهم على التفكير في المواقف والسلوكيات والاختيارات..» (ص 98)"},{"h":"المعيار 28: لا للمقارنة","x":"«المقارنات من المحبطات المدمرات للشخصية..» (ص 99)"},{"h":"المعيار 29: الغيرة بين الأبناء","x":"«امنح كل واحد منهم تفضيلات خاصة وفرصا جميلة للتواصل والحوار المفتوح..» (ص 99)"},{"h":"المعيار 30: البيت المضياف","x":"«اسمح لأبنائك باستقبال أصدقائهم بالبيت ليشعروا بقيمة بيئتهم المضيافة المرحبة..» (ص 99)"}]},{"t":"المعايير 31 إلى 40: حياة الأسرة اليومية","pg":100,"key":"تأكد دوما أن تدير حياتك من خلال فهم الأولويات وإدارتها بادئا بالأهم فالمهم..","p":["لا أحبها أبداً، بل أحب ابني كثيراً."],"items":[{"h":"المعيار 31: المشاركة","x":"«شجّع أبناءك المراهقين على مشاركة غيرهم بعض ممتلكاتهم من لعب وكتب وغيرها؛ مما يشجعهم على اكتساب المهارات الاجتماعية والقيم النبيلة..» (ص 100)"},{"h":"المعيار 32: أنشطة أسبوعية","x":"«خطط لبرامج وأنشطة أسبوعية تجمع كل أفراد الأسرة وتكون هادفة إلى تحقيق فوائد تربوية واجتماعية وتقوي العلاقات الإيجابية...» (ص 100)"},{"h":"المعيار 33: الأولويات","x":"«أسرتك شيء أساسي في حياتك وأولوية مهمة لا تعطها فضول وقتك..» (ص 101)"},{"h":"المعيار 34: احترام الوقت","x":"«قيمة احترام الوقت تساعد كثيرا في بناء الشخصية الإيجابية..» (ص 101)"},{"h":"المعيار 35: لوحة الرسائل","x":"«اقتناء وتعليق لوحة بالبيت لإرسال الرسائل واستقبالها فكرة متميزة في توطيد العلاقات الإيجابية..» (ص 101)"},{"h":"المعيار 36: تنظيم بلا إرغام","x":"«التنظيم والترتيب مهم داخل الأسرة ولكن دون إرغام ومبالغة..» (ص 102)"},{"h":"المعيار 37: التعاون في أعمال البيت","x":"اجعل أعمال البيت فرصة للتعاون بين الأبناء جميعا دون فصل حاد بين أعمال الولد وأعمال البنت. (ص 102)"},{"h":"المعيار 38: البيت ملكية عامة","x":"«أشعر الأبناء أن البيت ملكية عامة... والحفاظ عليه مسؤولية جماعية..» (ص 102)"},{"h":"المعيار 39: المال ليس كل شيء","x":"«المال ليس كل شيء.. الحب والمشاعر داخل البيت أهم.. والإيمان بالله أسمى النعم..» (ص 103)"},{"h":"المعيار 40: التدبير المالي","x":"«لا إسراف في المقتنيات.. التدبير المالي مهم.. ومراعاة الدخل في المصاريف قيمة ينبغي إدراكها من الجميع...» (ص 103)"}]},{"t":"المعايير 41 إلى 50: الدراسة والذات الوالدية والمدح","pg":103,"key":"التوتر لدى المربين أعدى أعداء العلاقة الإيجابية مع الأبناء","p":["قال خدمت رسول الله صلى الله عليه وسلم عشر سنوات فما قال لشيء فعلته لم فعلته، ولا لشيء لم أفعله لمَ لم تفعله، وما ضرب قط ولا رفع صوته..."],"items":[{"h":"المعيار 41: التلفاز يمكن إيقافه","x":"«جلسات الأسرة دون مثير ولا تلفاز، والاستمتاع بالحوارات أجمل من ألف متابعة سلبية واستقبال من طرف واحد..» (ص 103)"},{"h":"المعيار 42: متابعة الدراسة","x":"«دراسة الأولاد شيء أساسي وأولوية قصوى في حياة الأسرة ينبغي متابعتها، ولا يقبل التفريط فيها أو إهمال المتابعة..» (ص 104)"},{"h":"المعيار 43: رسائل المدرسة","x":"«تفاعل أكثر مع الرسائل الإيجابية، وارفع معنويات ابنك عند كل رسالة سلبية، وأعد له ثقته بنفسه؛ فهو أحوج ما يكون للدعم حينها.» (ص 104)"},{"h":"المعيار 44: أوقات خاصة للزوجين","x":"«العلاقة الأساسية والمحورية داخل الأسرة هي علاقة الزوج بزوجته، وهي أهم من العلاقة مع الأبناء.. فإذا حَسُنت تحسن غيرها..» (ص 105)"},{"h":"المعيار 45: حافظ على ذاتك","x":"«كلما ارتاح الوالدان كانا أقدر على العطاء والتربية الهادئة الإيجابية الصالحة..» (ص 105)"},{"h":"المعيار 46: لا تراكم للتوتر","x":"«لذلك يجب حل المشكلات الثانوية لدى الأسرة من أب وأم قبل مباشرة معالجة سلوك الأولاد.» (ص 106)"},{"h":"المعيار 47: لا للنقد المستمر","x":"«تخلص من النكد واللوم والنقد حتى لا تصبح ألما في حياة أبنائك..» (ص 107)"},{"h":"المعيار 48: المدح والدعم","x":"«البيئة التربوية الإيجابية يكثر فيها المدح والدعم والتشجيع بدل النقد واللوم والتحبيط...» (ص 107)"},{"h":"المعيار 49: تحدث عن تجربتك","x":"«لا يوجد فشل في الحياة وإنما الفشل قد يتحول لخبرات وتجارب نتعلم منها معنى النجاح وخطواته..» (ص 108)"},{"h":"المعيار 50: اجعلهم يحبون ما تريد","x":"«اجعل أبناءك يحبون ما تريد منهم.. حببهم في الصلاة وستراهم أكثر إقبالا عليها وأشد سرورا بها..» (ص 108)"}]}],"quiz":[{"q":"ما سر السعادة في الحياة الأسرية بحسب الكتاب؟","o":["المحبة الحقيقية بين أفراد الأسرة","الدخل المادي الكافي لكل الحاجات","الانضباط الصارم في كل أوقات البيت","كثرة النشاطات المشتركة خارج البيت"],"why":"يتلخص سر السعادة في الحياة الأسرية في كلمة واحدة هي: المحبة","pg":80},{"q":"أب يترصد أخطاء ابنه ويفضحه أمام إخوته. ما البديل الذي يقترحه الكتاب؟","o":["أن يضبطه وهو يحسن فيرفع معنوياته","أن يضاعف العقوبة حتى يرتدع تماما","أن يقارنه بأخيه المتفوق ليتحمس","أن يكثر من تهديده بعقوبات مؤجلة"],"why":"ضبط الأولاد وهم يخطئون وفضحهم لا فائدة منه.. الأفضل أن تبتسم وترفع المعنويات من خلال ضبطهم وهم يحسنون..","pg":97},{"q":"وصلت إلى الأب رسالة سلبية من المدرسة عن ابنه. ما التصرف الأنسب وفق الكتاب؟","o":["يرفع معنويات ابنه ويعيد إليه ثقته بنفسه","يحرمه من التلفاز حتى تتحسن درجاته","يوبخه أمام إخوته ليكون عبرة لهم في المستقبل","يتجاهل الرسالة ولا يحدثه عنها أبدا"],"why":"تفاعل أكثر مع الرسائل الإيجابية، وارفع معنويات ابنك عند كل رسالة سلبية، وأعد له ثقته بنفسه؛ فهو أحوج ما يكون للدعم حينها.","pg":104},{"q":"أي العلاقات يعدها الكتاب أساسية ومحورية داخل الأسرة؟","o":["علاقة الزوج بزوجته","علاقة الأب بأبنائه","علاقة الأم بأبنائها","علاقة الإخوة ببعضهم"],"why":"العلاقة الأساسية والمحورية داخل الأسرة هي علاقة الزوج بزوجته، وهي أهم من العلاقة مع الأبناء.. فإذا حَسُنت تحسن غيرها..","pg":105},{"q":"لماذا يحذر الكتاب من مبالغة الأب في إرغام أبنائه على التنظيم والترتيب؟","o":["لأنها قد تقتل سمة الإبداع لديهم","لأنها تعلمهم الكذب هربا من العقاب","لأنها تضيع وقت الأسرة في الثانويات","لأنها تثير الغيرة بين الإخوة في البيت"],"why":"ولا ترغمهم بمبالغات الأب أو الأم المنظم فقد يقتل سمة الإبداع لديهم..","pg":102}],"scene":{"t":"طلب في ليلة دراسية","x":"ابنك يطلب الخروج مع أصدقائه حتى وقت متأخر في ليلة امتحان، وتريد أن ترفض. كيف تفعل؟","opts":["تقول لا بهدوء وحزم وتشرح سببها دون صراخ","ترفع صوتك ليعرف أنك جاد في الرفض","تهدده بعقوبة كبيرة وإن كنت لن تنفذها"],"why":"يمكنك دوما قول (لا).. تعلّم كيف تقولها دون صراخ أو غضب أو عنف..","pg":93},"rel":[{"b":"teen","ci":3,"t":"توجيه المراهق"}]},{"k":"c4","t":"المهارة الأولى: تعلم فن الإنصات","q":"كيف ينصت المربي إلى ابنه المراهق إنصاتا فعالا؟","essence":"الأذن المصغية مفتاح قلب المراهق","kw":["الإنصات","الإصغاء الفاعل","آذان الفيلة"],"sections":[{"t":"أسس الإنصات","pg":110,"key":"إن الأذن المصغية في سن المراهقة هي الحل لمشكلاتها","p":["فالحقيقة ليست دوما ما يقوله الكبار، بل ما يكتشفه المراهق بنفسه."],"items":[{"h":"ابحث عن مجالات الاهتمام","x":"انتبه لما يهم ابنك في حديثه."},{"h":"احكم على المحتوى","x":"احكم على المحتوى وليس على طريقة الحديث."},{"h":"لا تتعجل بالتقييم","x":"أخر حكمك حتى ينتهي الحديث."},{"h":"أنصت إلى الأفكار","x":"التقط الأفكار الرئيسة لا الألفاظ وحدها."},{"h":"كن مرنا وتعمد الإنصات","x":"اجعل الإنصات قرارا واعيا لا مصادفة."},{"h":"قاوم التشتت وكن يقظا","x":"درّب عقلك واستفد من قاعدة أن التفكير أسرع من الحديث."}]},{"t":"11 مهارة للإنصات الفعال","pg":112,"key":"أحيانا كثيرة يحتاج الأبناء فقط لمن ينصت لهم باهتمام ويشعرهم بأهميتهم دون إعطائهم حلولا أو تقديم مساعدة..","p":["أفضل الإنصات إنصات العين...","أغلق التلفاز، وضع هاتفك على الصامت، وقل لابنك: أنا معك وكلي آذان مصغية.. وابتسم!!"],"items":[{"h":"1. حتى ينهي كلامه","x":"«أنصت لابنك دوما إلى أن ينهي كلامه واجتنب أن تتركه وتنصرف عنه وهو لم ينه كلامه أو تقاطعه قبل الانتهاء..» (ص 113)"},{"h":"3. انظر إليه","x":"«انظر لمن يحدثك وركّز عينيك عليه..» (ص 114)"},{"h":"5. التكرار","x":"«إن التكرار يعني إعادة ما قاله الآخر ومشاعره المرفقة بطريقتي الخاصة وأستخدام مفرداتي الخاصة.» (ص 115)"},{"h":"6. اختلاف إدراك الكلمات","x":"«فما يقصده الابن بالكلمة قد لا يكون ما يدركه الأب نفسه..» (ص 117)"},{"h":"7 و8. أجب وشجّع","x":"أجب عن أسئلة أبنائك ولا تتهرب، وشجّع حديثهم: «أن ينفتح أبناؤنا علينا خير من أن ينفتحوا على غيرنا...» (ص 118)"},{"h":"9. لغات التواصل كلها","x":"لا تركز على الكلمات وحدها، بل على تعبير الوجه والجسد ونغمة الصوت (ص 118)."},{"h":"10 و11. الختام وغياب المشتتات","x":"اسأله في نهاية الحوار عن حالته المزاجية، ولا تنصت له والتلفاز يعمل أو الهاتف يرن (ص 119)."}]},{"t":"أنواع المجالسة ومبدأ الإصغاء","pg":119,"key":"لقد تعلمنا منذ الصغر الكتابة والقراءة، التكلّم والرسم، التعليم والتمثيل... ولكن هل تعلمنا الإصغاء والحوار؟","p":["المراهق يحتاج إلى من يتفهم حالته النفسية ويراعي احتياجاته الجسدية؛ ولذا فهو بحاجة إلى صديق ناضج يجيب عن تساؤلاته بتفهم وعطف وصراحة، صديق يستمع إليه حتى النهاية دون مقاطعة أو سخرية أو شك"],"items":[{"h":"المجالسة الفوقية","x":"يجلس فيها الأب متعاليا، فتنتج المكابرة والعناد."},{"h":"المجالسة التحتية","x":"يغلب عليها الخوف وتنتج ضعف الشخصية."},{"h":"المجالسة المعتدلة","x":"تنتج الاطمئنان والصراحة، وهي المطلوبة."},{"h":"مهارات مبدأ الإصغاء","x":"أن أتوقف، وعدم التركيز على الذات، وأن أميز بين فكرة الآخر وشخصه، وأن أحافظ على الانفتاح، وشجاعة الاستقامة، وعامل الوقت (ص 120 و121)."},{"h":"أين ومتى تجالسه","x":"يعرض الكتاب أماكن المجالسة وأوقاتها المناسبة ومشكلات الإصغاء (ص 122 و123)."}]},{"t":"أسس الإصغاء الفاعل","pg":125,"key":"لذا فالإصغاء لا يرتكز فقط على الأذن بل على العين والقلب...","p":["لذا فالإصغاء ليس فقط إذا كنت تجيد تقنياته، بل يبدأ من مثلك الصادق الذي يوحي للآخر برغبة الانفتاح والثقة بك...","الإصغاء الفاعل رسالة مودة إلى القلوب قبل العقول"],"items":[{"h":"1. المثل الصالح","x":"يبدأ الإصغاء من قدوة صادقة توحي بالانفتاح والثقة."},{"h":"2. افهم الآخر كما هو","x":"«غاية الإصغاء الفاعل وقوته هما فهم الآخر واكتشافه كما هو وتشخيصه بموضوعية تامة بالنظر بمنظاره» (ص 126)"},{"h":"3. احرص على أن يفهمك الآخرون","x":"بخلق سليم، وشعور صادق، ومنطق واضح (ص 127)."}]},{"t":"آذان الفيلة","pg":130,"key":"لا أدري لماذا يخيل إليّ أن الآباء الجيدين والأمهات الجيدات يتمتعون بآذان كبيرة كآذان الفيلة، لعل مرد ذلك إلى كونهم يحسنون الإنصات، أو الاستماع الفاعل عندما يتحدث أبناؤهم","p":["قدرة الإنسان على الإنصات فيها تهذيب للنفس بضبطها وعدم اتباعها في شهوة التحدث بلا ضابط والتي قد تتسبب في انصراف أبنائنا عنا.","اصبروا... اصبروا.. ثم اصبروا فلن تبلغ أذانكما حجم آذان الفيلة إلا بالصبر."],"items":[{"h":"وصفة علاجية","x":"يصف المؤلف لحالة شاب حوارا يوميا لا يقل عن 30 دقيقة مع المدح (ص 131)."},{"h":"قول الشافعي","x":"«ما جادلت أحدا إلا وتمنيت أن يكون الحق على لسانه» (ص 133)"},{"h":"تعلّم من أبنائك","x":"«لا تكون دوما معلما لأبنائك.. بل تعلّم منهم أحيانا..» (ص 134)"}]}],"quiz":[{"q":"ابن يحكي لأبيه عن مشكلة تضايقه. ما الذي ينبه إليه الكتاب في هذا الموقف؟","o":["أنه قد يحتاج فقط لمن ينصت له باهتمام","أن على الأب تقديم الحل فور بدء الحديث","أن يقاطعه الأب ليوجهه إلى الصواب سريعا","أن يؤجل الحديث حتى تنتهي المشكلة وحدها"],"why":"أحيانا كثيرة يحتاج الأبناء فقط لمن ينصت لهم باهتمام ويشعرهم بأهميتهم دون إعطائهم حلولا أو تقديم مساعدة..","pg":113},{"q":"ما المقصود بمهارة التكرار في الإنصات الفعال؟","o":["إعادة ما قاله الابن ومشاعره بأسلوبي ومفرداتي","ترديد كلمات الابن نفسها حرفيا دون أي تغيير","تكرار النصيحة نفسها حتى يقتنع بها الابن","إعادة السؤال على الابن مرات كثيرة حتى يجيب عنه"],"why":"إن التكرار يعني إعادة ما قاله الآخر ومشاعره المرفقة بطريقتي الخاصة وأستخدام مفرداتي الخاصة.","pg":115},{"q":"على أي شيء يرتكز الإصغاء الفاعل بحسب الكتاب؟","o":["الأذن والعين والقلب معا","الأذن وحدها دون غيرها","الكلمات المنطوقة فقط","التقنيات المدربة وحدها"],"why":"لذا فالإصغاء لا يرتكز فقط على الأذن بل على العين والقلب...","pg":126},{"q":"أب يستمع لابنه والتلفاز يعمل والهاتف يرن بين حين وآخر. ما توصية الكتاب؟","o":["يغلق التلفاز ويضع هاتفه على الصامت ويبتسم","يؤجل الحديث كله إلى نهاية الأسبوع حين يتفرغ له","يطلب من ابنه أن يكتب ما يريد في ورقة","يكمل متابعته ويكتفي بهز رأسه موافقا"],"why":"أغلق التلفاز، وضع هاتفك على الصامت، وقل لابنك: أنا معك وكلي آذان مصغية.. وابتسم!!","pg":119}],"scene":{"t":"حديث لم يكتمل","x":"بدأ ابنك يحدثك عن موقف أزعجه في المدرسة، وأنت متعب وتريد إنهاء الحديث بسرعة. ماذا تفعل؟","opts":["تنصت إليه حتى ينهي كلامه دون مقاطعة ثم تسأله عن شعوره","تقاطعه وتعطيه الحل مباشرة لتختصر الوقت","تقول له: سنتحدث لاحقا، ثم تنصرف عنه"],"why":"أنصت لابنك دوما إلى أن ينهي كلامه واجتنب أن تتركه وتنصرف عنه وهو لم ينه كلامه أو تقاطعه قبل الانتهاء..","pg":113},"rel":[{"b":"teen","ci":3,"t":"توجيه المراهق"}]},{"k":"c5","t":"المهارة الثانية: التربية على الاختيار","q":"كيف نربي المراهق على الاختيار الحر المسؤول؟","essence":"اختيار حر ومسؤولية كاملة","kw":["الاختيار","الحرية","المسؤولية"],"sections":[{"t":"قدرات الإنسان الثلاث","pg":136,"key":"أنت لا يمكنك تغيير الآخرين لأنك لا تستطيع التحكم في سلوكياتهم. ولكن.. يمكنك تغيير نفسك فقط لأنك مسؤول عن اختيارك لسلوكياتك وتستطيع التحكم فيها","p":["أنت المسؤول وحدك عما تفكر فيه وتنفعل به وتفعله بما يحدد وظائف جسمك العضوية الفسيولوجية."],"items":[{"h":"1. توجيه السلوك","x":"يشمل السلوك عند د. بشير الرشيدي الأفعال والانفعالات والتفكير والوظائف العضوية."},{"h":"2. اختيار السلوك","x":"اختيارك سلوكياتك هو ما يميزك ويعود عليك بالسعادة أو التعاسة (ص 137)."},{"h":"3. تحمل المسؤولية","x":"أنت وحدك المسؤول عن سلوكياتك (ص 137)."}]},{"t":"مفهوم الاختيار وأسسه","pg":138,"key":"تفضيل شيء على آخر أو موقف على آخر أو شخص على آخر. ولكن إذا تعمقنا أكثر يمكن القول أن الاختيار هو اتخاذ قرار أو موقف يلتزم به الإنسان.","p":["لا يستطيع أن يختار إلا الإنسان الحر. والحرية هبة من الله وقدرة ينميها الإنسان ويتمرّن عليها.","فالإنسان لا يصبح إنساناً، ولا يكتمل نضجه إلا إذا عاش حريته في الاختيار."],"items":[{"h":"الحرية","x":"أساس الاختيار الأول، ومن معانيها عند جلاسر «أن يكون مسؤولاً عن كل عمل يقوم به، ولا يلقي اللوم على الآخرين.» (ص 140)"},{"h":"الوعي","x":"«استعمال العقل والموازنة في الاختيار...» (ص 141)"},{"h":"القيم","x":"سلم قيمي يرتب الأولويات: الله خالقي، ثم صحتي، ثم علاقاتي، ثم مهنتي وعلمي، ثم إمكانياتي المادية (ص 141)."},{"h":"لا تتدخل أحيانا","x":"«أحياناً اسمح لابنك أن يتحمل مسؤولية اختياره لسلوك غير مرغوب فيه فلا تتدخل...» (ص 139)"}]},{"t":"مراحل الاختيار وكيف نربي عليه","pg":142,"key":"لا بد من تربية ذواتنا على الاختيار السليم لنربي أولادنا عليه.","p":["مناقشة أي قرار يتم اختياره، وتأكيد نتائجه، مثلاً: شراء جهاز معين، أو الخروج بنزهة، أو وجهة سفر لقضاء إجازة."],"items":[{"h":"مراحل الاختيار الأربع","x":"دراسة الواقع، ثم اتخاذ القرار بعد الموازنة، ثم تنفيذه والالتزام به، ثم مناقشة النتائج (ص 142)."},{"h":"أولا: بالتجربة اليومية","x":"مناقشة القرارات اليومية وتأكيد نتائجها (ص 142)."},{"h":"ثانيا: بالإشراك","x":"«أي إشراك الأولاد في الاختيارات التي تهم الأسرة بكاملها، كيف سنحتفل هذه السنة بعيد الفطر مثلاً؟» (ص 143)"},{"h":"ثالثا: بالتمرين","x":"تمرين الابن على اختيار ساعة النوم وأسبابها، والألعاب، واللباس، والأصدقاء (ص 143)."},{"h":"رابعا: بالحرية المسؤولة","x":"«الحرية المسؤولة تعني التخلي عن أنانيته ومحوريته والانفتاح على الآخر.» (ص 143)"}]},{"t":"الحرية والمسؤولية والاختيارات المصيرية","pg":143,"key":"علينا أن نوفر لأبنائنا جوا سليما يساعدهم على الاختيار السليم.","p":["إن قراراتنا هيَ التي تكونا، فإننا نبني حياتنا الأبدية يوماً بعد يوم، دقيقة بعد دقيقة وقراراً بعد قرار. كل قرار هو حجر في بناء ذاتنا وبناء حياتنا."],"items":[{"h":"الحرية باختصار","x":"«القدرة دون إجبار من أحد على اتخاذ قرار ما باستخدام ما هو متاح من معلومات للاختيار بين بدائل تحقق هدفاً محدداً.» (ص 143)"},{"h":"المسؤولية باختصار","x":"«الاستعداد لتحمّل كامل النتائج المترتبة أو التي ستترتب على ذلك الاختيار» (ص 144)"},{"h":"الاختيارات المصيرية","x":"المهنة، والاتجاه الفكري، وشريك الحياة (ص 144)."},{"h":"عاقبة الاختيار غير السليم","x":"«إن الاختيار غير السليم يؤدي إلى تفكك الأسرة والطلاق» (ص 145)"}]}],"quiz":[{"q":"لماذا لا يستطيع الأب أن يغير ابنه تغييرا مباشرا بحسب ما ينقله الكتاب؟","o":["لأنه لا يتحكم في سلوك غيره بل في سلوكه هو","لأن المراهق لا يسمع إلا من أصدقائه المقربين","لأن السلوك موروث لا يتعدل بعد سن الطفولة","لأن الأب لا يملك وقتا كافيا لمتابعة ابنه"],"why":"أنت لا يمكنك تغيير الآخرين لأنك لا تستطيع التحكم في سلوكياتهم. ولكن.. يمكنك تغيير نفسك فقط","pg":136},{"q":"أي مما يلي مثال على التربية على الاختيار بطريقة الإشراك؟","o":["سؤال الأبناء: كيف سنحتفل هذه السنة بالعيد؟","ترك الابن يقرر وحده كل شيء دون أي مناقشة سابقة","اختيار الأب لابنه ملابسه وأصدقاءه عنه","مكافأة الابن كلما وافق على اختيار والده"],"why":"أي إشراك الأولاد في الاختيارات التي تهم الأسرة بكاملها، كيف سنحتفل هذه السنة بعيد الفطر مثلاً؟","pg":143},{"q":"ما المرحلة التي تلي اتخاذ القرار في مراحل الاختيار الأربع؟","o":["تنفيذ القرار والالتزام به","دراسة الواقع والموازنة","مناقشة النتائج وتقويمها","استشارة الأصدقاء المقربين"],"why":"تنفيذ القرار أي الالتزام بما قررت واخترت","pg":142},{"q":"كيف يعرّف الكتاب المسؤولية باختصار؟","o":["الاستعداد لتحمل كامل النتائج المترتبة على الاختيار","القدرة على اتخاذ القرار دون إجبار من أحد","إلقاء اللوم على من تسبب في الخطأ من الآخرين دائما","الالتزام بأوامر الكبار دون السؤال عن أسبابها"],"why":"الاستعداد لتحمّل كامل النتائج المترتبة أو التي ستترتب على ذلك الاختيار (أي اتخاذ ذلك القرار).","pg":144},{"q":"ابن اختار سلوكا غير مرغوب لكنه غير خطير. ما الذي يجيزه الكتاب للأب أحيانا؟","o":["أن يتركه يتحمل نتيجة اختياره فلا يتدخل","أن يتدخل فورا ويختار عنه البديل الأصح","أن يعاقبه حتى لا يكرر الاختيار نفسه","أن يلوم أصدقاءه لأنهم سبب سوء اختياره"],"why":"أحياناً اسمح لابنك أن يتحمل مسؤولية اختياره لسلوك غير مرغوب فيه فلا تتدخل...","pg":139}],"scene":{"t":"وجهة الإجازة","x":"تخطط الأسرة لإجازة الصيف، ويبدي أبناؤك آراء مختلفة في الوجهة. ماذا تفعل؟","opts":["تشركهم في دراسة الخيارات واختيار الوجهة ثم تناقش معهم النتائج","تختار الوجهة وحدك ثم تخبرهم بها لتجنب الخلاف","تتركهم يقررون كل شيء دون أي نقاش أو موازنة"],"why":"مناقشة أي قرار يتم اختياره، وتأكيد نتائجه، مثلاً: شراء جهاز معين، أو الخروج بنزهة، أو وجهة سفر لقضاء إجازة.","pg":142},"rel":[{"b":"lebon","ci":6,"t":"الكتاب الرابع: مسألة التربية"},{"b":"teen","ci":5,"t":"التعامل مع مشكلات المراهقين"}]},{"k":"c6","t":"المهارة الثالثة: اسع أولا لتفهم ثم لتكون مفهوما","q":"كيف نفهم المراهق أولا ثم نجعله يفهمنا؟","essence":"افهم أولا ثم اطلب أن تفهم","kw":["التقمص العاطفي","التغذية الراجعة","الفهم"],"sections":[{"t":"الاستماع بالتقمص العاطفي","pg":146,"key":"إن الاستماع بهدف الوصول إلى داخل عقل وقلب الآخر يُدعى الاستماع بالتقمص العاطفي","p":["هل تعتقد أن المراهقين في أسرتك يرون العالم كما تراه؟ فكّر ثانية! إنهم يرون العالم من خلال تجاربهم.","إنه المحاولة لكي ترى العالم من خلال عيني الآخر"],"items":[{"h":"أصل المهارة","x":"يذكر الكتاب أنها مأخوذة من العادات السبع للأسر الأكثر فعالية لأسرة كوفي (ص 146)."}]},{"t":"خمسة طرائق للاستماع","pg":149,"key":"أرقى أنواع الاستماع.. أن تستوعب الإطار المرجعي للمتكلم","p":[],"items":[{"h":"1. التجاهل","x":"لا يستمع المرء أصلا."},{"h":"2. التظاهر بالاستماع","x":"يبدو مستمعا وهو غائب الذهن."},{"h":"3. الاستماع الانتقائي","x":"يلتقط ما يهمه من الحديث فقط."},{"h":"4. الاستماع الفعال اليقظ","x":"ينتبه للكلمات لكن من إطاره هو."},{"h":"5. الاستماع بالتقمص العاطفي","x":"يكون ضمن الإطار المرجعي للمتكلم، وهو أرقاها."}]},{"t":"حدود الاستماع: أربع استجابات","pg":151,"key":"الاستماع بالتقمّص العاطفي هو طريقك لتفهّم الآخر...","p":[],"items":[{"h":"التقييم","x":"«الحكم وإعطاء قيمة أو عدم الموافقة» (ص 151)"},{"h":"الاستجواب","x":"«هو طرح الأسئلة من وجهة نظرنا واهتماماتنا أو أولوياتنا» (ص 151)"},{"h":"النصح","x":"«إعطاء التوجيه والإرشاد والحلول للمشكلات» (ص 151)"},{"h":"التفسير","x":"«وهو شرح دوافع الآخر وسلوكه اعتماداً على خبرتنا الخاصة» (ص 151)"}]},{"t":"النصف الثاني: أن تكون مفهوما","pg":152,"key":"إن البحث عن أن تفهم يتطلب العطاء، ولكن البحث عن أن تُفهم يتطلب الشجاعة.","p":["وهذا يكون بأن تشارك الآخرين بالطريقة التي ترى فيها العالم، ويكون ذلك بالتغذية الراجعة وبالشجاعة وبأن تعطي الحب للآخر.","المقصود من التغذية الراجعة هو تزويد الآخرين بالمعلومات والتوقعات الكافية حول سلوكك وموقفك وقراراتك بوضوح وصراحة قدر المستطاع."],"items":[{"h":"سؤال قبل التغذية الراجعة","x":"هل هذه التغذية الراجعة إيجابية أم أنها فقط لتلبي حاجتي؟ وهل يهمني أن أفهم أولا؟ (ص 153)"},{"h":"افصل بين الشخص وسلوكه","x":"كما فعل لوط عليه السلام: لم يكره قومه وإنما كره سلوكهم «إني لعملكم من القالين» (ص 153)"},{"h":"ضمير أنا","x":"استخدم في لغتك ضمير «أنا» لتشرك الآخرين بمفاهيمك، لا ضمير «أنت» (ص 153)."},{"h":"المنطقة العمياء","x":"«كل إنسان لديه منطقة \"عمياء\" في داخله حيث لا يرى ما يحتاجه ليتحسن ويتغيّر نحو الأفضل» (ص 157)"}]},{"t":"8 خطوات لفهم أفضل","pg":154,"key":"إذا كان أسلوبك التربوي لا يفيد في إصلاح سلوك ابنك، فلماذا لا تغيّره؟!","p":[],"items":[{"h":"1. اسأله عن شعوره","x":"«تذكر أن تسأله: هل تشعر أنني أفهمك؟» (ص 154)"},{"h":"2. أصلح سوء الفهم","x":"ابحث عن وقت تنفرد فيه بفرد من الأسرة حصل بينكما سوء فهم، وأخبره أنك تريد أن تفهمه أفضل (ص 154)."},{"h":"3. على مائدة الطعام","x":"اسأل كل فرد عن شيء تمتع به في يومه، وحاول أن تفهم أهمية ما يقول (ص 155)."},{"h":"4. كيف حالك؟","x":"اختر وقتا تسأل فيه كل فرد عن حاله وجرب الاستماع بتقمص عاطفي (ص 155)."},{"h":"5. وقت التنقل","x":"اسأل أبناءك في السيارة عن أجمل خبرة اكتسبوها هذا الأسبوع بدل المذياع (ص 155)."},{"h":"6. يوم استماع","x":"«إذا كنت كثير الكلام، خذ استراحة وأمض يومك مستمعاً، فقط تكلّم عندما يجب ذلك.» (ص 155)"},{"h":"7. عبر عن مشاعرك","x":"لا تخف مشاعرك بل عبر عنها بطريقة مسؤولة وإيجابية (ص 155)."},{"h":"8. تغذية راجعة نافعة","x":"فكر في تغذية راجعة إيجابية تساعد الآخر وتدرب عليها (ص 155)."}]}],"quiz":[{"q":"ما أرقى أنواع الاستماع، وهو الذي يستوعب الإطار المرجعي للمتكلم؟","o":["التقمص العاطفي","الاستماع اليقظ","الاستماع الانتقائي","التظاهر بالاستماع"],"why":"أرقى أنواع الاستماع.. أن تستوعب الإطار المرجعي للمتكلم","pg":149},{"q":"حكى ابن عن خلاف مع معلمه، فبادره أبوه: فعلت ذلك لأنك تحب لفت الانتباه. أي استجابة هذه؟","o":["استجابة التفسير","استجابة التقييم","استجابة الاستجواب","استجابة النصح"],"why":"وهو شرح دوافع الآخر وسلوكه اعتماداً على خبرتنا الخاصة","pg":151},{"q":"إذا كان البحث عن أن تفهم الآخر يتطلب العطاء، فماذا يتطلب البحث عن أن تكون مفهوما؟","o":["يتطلب الشجاعة","يتطلب الصبر","يتطلب الصمت","يتطلب المدح"],"why":"إن البحث عن أن تفهم يتطلب العطاء، ولكن البحث عن أن تُفهم يتطلب الشجاعة.","pg":152},{"q":"ما المقصود بالتغذية الراجعة في هذه المهارة؟","o":["تزويد الآخرين بمعلومات واضحة عن سلوكك وموقفك وقراراتك","تقييم سلوك الابن وإصدار حكم عليه بعد كل موقف يمر به يوميا","إعطاء الابن نصائح وحلولا جاهزة لمشكلاته اليومية","سؤال الابن أسئلة كثيرة عن تفاصيل يومه واهتماماته"],"why":"المقصود من التغذية الراجعة هو تزويد الآخرين بالمعلومات والتوقعات الكافية حول سلوكك وموقفك وقراراتك بوضوح وصراحة قدر المستطاع.","pg":157},{"q":"أب كثير الكلام في جلسات الأسرة. ما الخطوة التي تقترحها خطوات الفهم الأفضل؟","o":["أن يأخذ استراحة ويمضي يومه مستمعا","أن يقلل جلسات الأسرة إلى مرة في الشهر","أن يطلب من أبنائه الكلام بعد انتهائه","أن يكتب نصائحه في رسائل بدل الكلام"],"why":"إذا كنت كثير الكلام، خذ استراحة وأمض يومك مستمعاً، فقط تكلّم عندما يجب ذلك.","pg":155}],"scene":{"t":"كلام من القلب","x":"جلس ابنك يحدثك بصدق عن شعوره بأن أحدا لا يفهمه في البيت. ماذا تفعل في نهاية حديثه؟","opts":["تسأله: هل تشعر أنني أفهمك؟","تعطيه حلا سريعا وتنهي الحديث","تحكي له تجربتك المشابهة بالتفصيل"],"why":"عندما تكون مع شخص وحاول أن يقول لك شيئاً من القلب، تذكر أن تسأله: هل تشعر أنني أفهمك؟","pg":154}},{"k":"c7","t":"المهارة الرابعة: التكاتف الأسري","q":"كيف تعمل الأسرة فريقا واحدا يحل مشكلاته معا؟","essence":"أسرة فريق واحد يحتفي بالاختلاف","kw":["التكاتف","العصف الذهني","الخيار الثالث"],"sections":[{"t":"مفهوم التكاتف","pg":158,"key":"التكاتف هو أن اثنين أو أكثر من أعضاء العائلة ... يتعاونون ليحصلوا على نتائج أفضل من أن يعمل كل على حدة.","p":["تماماً كما أن فريق العمل ضروري كما هو الفريق الرياضي الناجح، فإن تقدير الاختلافات في العائلة وتقييمها وتثمينها جوهرية للأسرة الناجحة.","لكي تخلق وتبني التوافق، عليك أن تبحث عنه، وعليك أن ترى أن لكل واحد كياناً فريداً، وأن تقدر ذلك التفرد."],"items":[{"h":"التناغم","x":"الاحتفاء بالاختلاف، والكل فريق عمل، وعقل مفتوح وسعة أفق، والبحث الدائم عن طرائق جديدة أفضل (ص 159)."},{"h":"التنافر","x":"تحمل الاختلاف مشقة، وكل يعمل عملا مستقلا، وأفكر أنني وحدي دوما على حق، وتغليب الحلول الوسط (ص 159)."},{"h":"الاختلاف أمر طبيعي","x":"«الاختلاف بينك وبين ابنك أمر طبيعي... والأهم أن تتقبله كما هو.» (ص 160)"}]},{"t":"السرطانات الأربعة التي تشل الفريق العائلي","pg":161,"key":"هذه السرطانات قاتلة لتركيبة الأسرة الناجحة؛ لأنها تنشر أثرها السلبي في قلب الأسرة وكيانها.","p":["ساعدني على أن أتعلّم من أخطائي بدلاً من أن تلومني عليها طوال الوقت"],"items":[{"h":"النقد","x":"أول السرطانات الأربعة."},{"h":"اللوم والشكوى","x":"يقول مراهق في الرابعة عشرة: «لو لم تعجبك درجاتي فيجب عليك أن تشجعني وتساعدني في عملي بدلاً من الاعتراض عليه والصراخ في وجهي نقداً ولوماً...» (ص 161)"},{"h":"المقارنة","x":"تقتل روح الفريق وتحبط الأبناء."},{"h":"التناحر أو التنافس","x":"يحول أفراد الأسرة إلى خصوم بدل أن يكونوا فريقا."}]},{"t":"خطة عمل لإنجاز التكاتف","pg":164,"key":"الطريق الوحيد لمعرفة درجة فعالية البديل والمحك الوحيد له هو وضعه موضع التنفيذ الفعلي.","p":["العصف الذهني أحد الطرائق المهمة في توليد الأفكار، وخلاصة هذه الطريقة تعتمد على أن يذكر كل شخص من المجموعة ما يرد عليه من أفكار حول المشكلة مهما كانت قيمتها"],"items":[{"h":"1. حدد المشكلة","x":"حدد المشكلة أو المناسبة المعينة."},{"h":"2. طريقهم","x":"ابحث أولا أن تفهم أفكار الآخرين."},{"h":"3. طريقي","x":"ابحث عن أن تكون مفهوما بإشراك الآخرين بأفكارك."},{"h":"4. العصف الذهني","x":"ابتكر خيارات وأفكارا جديدة."},{"h":"5. الطريق الأمثل","x":"أوجدوا الحل الأفضل، وهو الخيار الثالث."},{"h":"الأسلوب العلمي لتحليل المشكلات","x":"إدراك المشكلة، وتعريفها، وجمع المعلومات الضرورية، وتحليلها، ووضع البدائل الممكنة (ص 171)."}]},{"t":"قصص من حالات عدة","pg":166,"key":"ادعم ابنك عاطفيا وعبّر له عن حبك غير المشروط.. قبل أن تناقش معه سلوكا يزعجك","p":["\"إنه من الخطأ أن نقوم بالأمر نفسه مراراً وتكراراً ونتوقع نتائج مختلفة\".","شعر الشاب أنه فهم من قبل أبيه من دون أسلوب الاتهام المضاد أو المحاضرة."],"items":[{"h":"الحالة الأولى: تنظيف الغرفة","x":"طفل في السابعة لا ينظف غرفته، فتركت أمه التوبيخ وجلست تستمع إليه، فاتفقا على حل (ص 166 و167)."},{"h":"الحالة الثانية: العودة إلى الدروس","x":"فتاة في الثانوية تغيب عن المدرسة، لم يجد معها الوعظ، فعبر أبوها عن حبه أسبوعين ثم استمع إليها حتى انفتحت (ص 169 و170)."},{"h":"الحالة الثالثة: شراء سيارة","x":"أدرك الأب أن رغبة ابنه الحقيقية توفير الوقت والموازنة بين واجباته ومتعته، فتوصلا إلى اتفاق (ص 172)."},{"h":"مهارات مستفادة","x":"توافق نفسيا مع ابنك، وعبر عما يزعجك، وأنصت لوجهة نظره، وابحثا عن الحل (ص 170)."}]},{"t":"10 خطوات لبناء أسرة متكاتفة","pg":175,"key":"يحيا الحب بالتكاتف..... وتقوم الحياة على ساعد التكاتف... لا قيمة للحياة بلا حب ولا حب بلا تكاتف..","p":["الأمسيات الحوارية تساعد على الاستقرار الأسري.. احرص وداوم عليها.."],"items":[{"h":"1. جرب عادة التكاتف","x":"عند أي سوء تفاهم: حدد المشكلة، واستمع للآخرين، وأشركهم بوجهة نظرك، ومارس العصف الذهني، وأوجد الحل الأفضل."},{"h":"2. اسأل نفسك","x":"هل تسير الأمور في أسرتي سيرا متوافقا؟ وهل يتقبل الجميع الفروق الفردية؟"},{"h":"3. فكر بزواجك","x":"ما الاختلافات التي جذبت كلا منكما إلى الآخر؟ وكيف تثمنها؟"},{"h":"4. ثمن النعم","x":"«خذ بعين الاعتبار المهارات والقدرات والاهتمامات لكل فرد، ثم ابحث عن طريقة لتثمين النعم وتقديرها.» (ص 176)"},{"h":"5. أمسية نقاشية","x":"شجع كل أفراد العائلة على المشاركة، وأظهر تقديرك لنقاط قوتهم."},{"h":"6. نشاط مشترك","x":"اختر نشاطا يعمل فيه الجميع معا، كل بحسب مهارته."},{"h":"7. المشورة اليومية","x":"«واعقد العزم أن تسألهم المشورة مرة في اليوم على الأقل.» (ص 177)"},{"h":"8. وجبة عائلية","x":"خطط لوجبة يتعاون فيها الجميع، ووضح كيف أعطت المكونات المختلفة شيئا جديدا."},{"h":"9. تعلم من خلاف","x":"ناقش خلافا مع شخص أزعجك، وما الذي تعلمته منه."},{"h":"10. تأمل الطبيعة","x":"لاحظ كيف يخيم التوافق على الأسرة كما تعمل اليدان معا."}]},{"t":"قصة: إلى كل من لديه أم عظيمة لم يقدرها","pg":178,"key":"الطفل الذي تتم حمايته وتدليله وتعويده على الحصول على كل ما يريد؛ ينشأ على (عقلية الاستحقاق) ويضع نفسه ورغباته قبل كل شيء، وسينشأ جاهلا بجهد أبويه","p":["إذا كان هذا النوع هو الذي نربيه من الأولاد، فماذا نقصد؟ هل نحن نحميهم أم ندمرهم؟"],"items":[{"h":"القصة","x":"شاب متفوق يتقدم لوظيفة، فيطلب منه المدير أن يغسل يدي أمه التي كانت تغسل الثياب للناس لتنفق على دراسته (ص 178 إلى 180)."},{"h":"أولا","x":"«أدركت معنى العرفان بالجميل، فلولا أمي وتضحيتها لم أكن ما أنا عليه الآن من التفوق.» (ص 181)"},{"h":"ثانيا","x":"«بالقيام بالعمل نفسه الذي كانت تقوم به، أدركت كم هو شاق ومجهد القيام ببعض الأعمال.» (ص 181)"},{"h":"ثالثا","x":"«أدركت أهمية العائلة وقيمتها.» (ص 181)"},{"h":"الدرس التربوي","x":"«عندما ينتهي من الأكل، دعه يغسل طبقه مع إخوته.» (ص 183)"}]}],"quiz":[{"q":"ما الذي يحدث حين يتعلم أفراد الأسرة أن ينتفع كل منهم بمهارات الآخر؟","o":["يبدعون أكثر مما لو عملوا فرادى","تزول الاختلافات بينهم كلها","يتنافسون فيرتفع مستوى كل منهم","تقل حاجتهم إلى الحوار المشترك"],"why":"عندما يتعلم أعضاء فريق على أن ينفع وينتفع كل منهم بمهارات الآخر، فإنهم سيبدعون كثيراً مما لو كانوا يعملون بشكل فردي.","pg":160},{"q":"لماذا وصف الكتاب النقد واللوم والمقارنة والتناحر بالسرطانات؟","o":["لأنها تنشر أثرها السلبي في قلب الأسرة وكيانها","لأنها تظهر فجأة دون أي مقدمات واضحة في حياة الأسرة","لأنها تصيب الأبناء الصغار دون المراهقين","لأنها لا تعالج إلا بمختص من خارج الأسرة"],"why":"هذه السرطانات قاتلة لتركيبة الأسرة الناجحة؛ لأنها تنشر أثرها السلبي في قلب الأسرة وكيانها.","pg":161},{"q":"في حالة الطفل الذي يرفض تنظيف غرفته، ما الذي غيّر الموقف؟","o":["جلوس أمه معه والاستماع إليه بهدوء","زيادة التوبيخ والعقاب حتى يستجيب","تنظيف الأم الغرفة بنفسها كل يوم","مكافأته بهدية كلما رتب غرفته"],"why":"قررت أنها تحتاج إلى أن تقضي وقتاً في الاستماع لطفلها. لقد اقتنعت بالفكرة حتى جلست مع ابنها ليتحدثا بهدوء.","pg":166},{"q":"في حالة المراهق الذي يريد شراء سيارة، ماذا اكتشف الأب حين بحث عن حل؟","o":["أن رغبة ابنه الحقيقية توفير الوقت والموازنة بين واجباته","أن ابنه يريد التفاخر بالسيارة الجديدة أمام أصدقائه في المدرسة","أن ابنه لا يملك المال الكافي لشراء سيارة مناسبة له","أن ابنه يريد الابتعاد عن البيت وقضاء وقته خارجه"],"why":"لقد علم الأب أن رغبة ابنه الحقيقية هي وجود السيارة في حوزته وتوفير الوقت بشكل أحسن بحيث يوازن بين واجباته المدرسية ومتعته مع أصدقائه.","pg":172},{"q":"بحسب الفائدة من قصة الأم العظيمة، على أي شيء ينشأ الطفل الذي يدلل ويعطى كل ما يريد؟","o":["عقلية الاستحقاق","روح التكاتف الأسري","العرفان بالجميل","تحمل المسؤولية"],"why":"الطفل الذي تتم حمايته وتدليله وتعويده على الحصول على كل ما يريد؛ ينشأ على (عقلية الاستحقاق) ويضع نفسه ورغباته قبل كل شيء","pg":182}],"scene":{"t":"غياب عن المدرسة","x":"ابنك في المرحلة الثانوية يتهرب من دروسه ويكثر الغياب، ونصحك ووعظك له لم يجد نفعا. ماذا تفعل؟","opts":["تعبر له عن حبك ودعمك بانتظام، ثم تفتح الحوار وتستمع إليه","تضاعف الوعظ والتوبيخ حتى يعود إلى دروسه","تعاقبه بحرمانه من أصدقائه حتى يلتزم"],"why":"ادعم ابنك عاطفيا وعبّر له عن حبك غير المشروط.. قبل أن تناقش معه سلوكا يزعجك","pg":169}},{"k":"c8","t":"المهارة الخامسة: اللمسة الأبوية","q":"كيف يعبر الأب عن حبه وحنانه لابنه بالفعل والكلمة؟","essence":"لمسة حنان وكلمة حب","kw":["الحنان","الكلمة","احترام الذات"],"sections":[{"t":"أولا: اللمسة","pg":184,"key":"اترك أعمالك وعلاقاتك الاجتماعية، وعد إلى المنزل سعيداً، وكن سعيداً بوجودك مع أسرتك","p":["تخلص من ساعتك وأغلق هاتفك المحمول وعش حياتك بمتعة مع أفراد أسرتك"],"items":[{"h":"مصدر الوصفة","x":"«وصفة أخي المبدع الدكتور محمد فهد الثويني» (ص 184)"},{"h":"1 و2","x":"لمسة الرأس وفرك فروة الشعر، ولمسة الوجه والقبلة."},{"h":"3 و4","x":"لمسة الظهر والكتف، والحضن والضمة على الصدر (ص 185)."},{"h":"5 و6 و7","x":"لمس مواطن الألم، ولمس الرقبة، ولمس اليد (ص 185)."},{"h":"8 و9","x":"تشبيك اليد، وتشبيك أصابع اليد (ص 186)."},{"h":"10 و11 و12","x":"التدليك ولاسيما للرجل، ولمس القدم، ولمس الجسم بالجسم كالكتف بالكتف (ص 186)."}]},{"t":"ثانيا: الكلمة","pg":187,"key":"أمي: توقفي عن الحديث في الهاتف وتعالي للتحدث معي. والدي: عد للبيت مبكراً حتى نتناول العشاء معاً، ونتجاذب أطراف الحديث...","p":["إن \"البستاني\" الحصيف لا يلوم إلا نفسه إن نبتت الشجرة التي يرعاها هزيلة ضعيفة"],"items":[{"h":"ما يحب الأبناء سماعه","x":"«أريد أن أفهمك..» و«أنا فخور بك..» و«أنا حاضر.. يمكن أن أستمع إليك متى احتجتني..» و«أثق بك..» و«أنا أحبك..» (ص 187)"},{"h":"ما يحب الآباء سماعه عن الابن","x":"أنه ناجح، وملتزم بالعبادات، وخلوق حسن المعاملة، ومطيع خدوم، ويقول حاضر دون تأفف (ص 188)."}]},{"t":"ابنك واحترام الذات","pg":189,"key":"يعد احترام الذات من أعظم الهدايا التي يمكن لوالد أن يقدمها لابنه المراهق.","p":["يقع العديد من الآباء في خطأ مدح الإنجازات الكبيرة فقط، ولكن تذكّر أن المراهقين يحتاجون للمدح والتشجيع طوال الوقت."],"items":[{"h":"أثر احترام الذات","x":"«فالمستوى العالي من احترام الذات قد يشجع المراهق على تجربة أمور جديدة، أو يساعده على اتخاذ القرار الصحيح في كل مفترق طرق.» (ص 189)"},{"h":"صوت مراهقة","x":"«اجعلني أنشأ فخورة بذاتي، كي أكون واثقة بنفسي وأكون شخصية ذات قيمة» (ص 189)"},{"h":"صوت مراهق","x":"«قليل من الدعم سوف يساعدني على زيادة ثقتي بنفسي، توقف عن النظر إلى الجوانب السلبية لدي، وانظر إلى الجوانب الإيجابية» (ص 190)"}]},{"t":"خلاصات","pg":208,"key":"هكذا نربي... قدّم للقارئ محاولة جديدة لتشكيل ثقافة تربوية مبنية على المعايير والقيم والمهارات والمعرفة...","p":["مع المعايير قدمت خمس مهارات لازمة وأساسية لممارسة تربوية ناجحة، ولإعداد المربي المتسلح بالمهارات التربوية الحياتية..."],"items":[{"h":"الخلاصة","x":"من خلال المعايير يمكن ممارسة الوالدية بفاعلية وإيجابية إذا تحولت إلى مهارات وانطلقت من قيم وتأسست على معرفة علمية بشخصية المراهق (ص 208)."}]}],"quiz":[{"q":"ممن أخذ المؤلف وصفة مواضع اللمسة الأبوية؟","o":["د. محمد فهد الثويني","د. بشير الرشيدي","د. إبراهيم الخليفي","د. مصطفى السباعي"],"why":"وصفة أخي المبدع الدكتور محمد فهد الثويني","pg":184},{"q":"أي العبارات التالية مما يحب الأبناء أن يسمعوه من آبائهم؟","o":["أنا فخور بك","أنت تشبه أباك","لماذا لم تنجح؟","افعل ما أقول"],"why":"أنا فخور بك..","pg":187},{"q":"ما الخطأ الذي يقع فيه كثير من الآباء في مدح أبنائهم المراهقين؟","o":["قصر المدح على الإنجازات الكبيرة","المدح أمام الإخوة والأقارب والضيوف","مدح الابن على صفاته الخلقية","الإكثار من المدح في الطفولة"],"why":"يقع العديد من الآباء في خطأ مدح الإنجازات الكبيرة فقط، ولكن تذكّر أن المراهقين يحتاجون للمدح والتشجيع طوال الوقت.","pg":190},{"q":"يقول ابن لأبيه: عد للبيت مبكرا حتى نتناول العشاء معا. ما الذي يوصي به الكتاب الأب؟","o":["أن يترك أعماله ويعود سعيدا بوجوده مع أسرته","أن يعوض غيابه بشراء الهدايا الثمينة لأبنائه","أن يكلف غيره بالجلوس مع أبنائه وقت العشاء","أن يشرح لابنه أن العمل أهم من العشاء"],"why":"اترك أعمالك وعلاقاتك الاجتماعية، وعد إلى المنزل سعيداً، وكن سعيداً بوجودك مع أسرتك","pg":185},{"q":"ما الذي يعده الكتاب من أعظم الهدايا التي يقدمها الوالد لابنه المراهق؟","o":["احترام الذات","المال الوفير","الهاتف الحديث","الحرية المطلقة"],"why":"يعد احترام الذات من أعظم الهدايا التي يمكن لوالد أن يقدمها لابنه المراهق.","pg":190}],"scene":{"t":"عودة حزينة","x":"عاد ابنك من المدرسة حزينا وجلس بجانبك، وأنت منشغل بهاتفك ورسائل العمل. ماذا تفعل؟","opts":["تغلق هاتفك وتضمه وتقول له: أنا حاضر، أستمع إليك","تسأله سؤالا سريعا ثم تعود إلى هاتفك","تعطيه مالا ليشتري ما يفرحه"],"why":"تخلص من ساعتك وأغلق هاتفك المحمول وعش حياتك بمتعة مع أفراد أسرتك","pg":186}}],"highlights":[{"x":"إن لم تضف شيئاً على الحياة كنت أنت الزائد عليها.","pg":13},{"x":"التربية فهم قبل أن تكون ممارسة","pg":15},{"x":"أنصت لأبنائك في الصغر ينصتون لك في الكبر...","pg":89},{"x":"20 دقيقة حوار يومي تجعل منك صديقا عزيزا في حياة أبنائك..","pg":90},{"x":"الصراخ من خوارم الوقار والمروءة لا أحد يعجب بشخص يصرخ..","pg":93},{"x":"إذا أردت أن ينشأ أبناؤك كالصقور؛ فعلمهم أن يحلقوا عاليا ولوحدهم..","pg":96},{"x":"المقارنات من المحبطات المدمرات للشخصية..","pg":99},{"x":"أسرتك شيء أساسي في حياتك وأولوية مهمة لا تعطها فضول وقتك..","pg":101},{"x":"تخلص من النكد واللوم والنقد حتى لا تصبح ألما في حياة أبنائك..","pg":107},{"x":"إن الأذن المصغية في سن المراهقة هي الحل لمشكلاتها","pg":110},{"x":"إن البحث عن أن تفهم يتطلب العطاء، ولكن البحث عن أن تُفهم يتطلب الشجاعة.","pg":152},{"x":"لا قيمة للحياة بلا حب ولا حب بلا تكاتف..","pg":175}],"concepts":[{"term":"هدف التربية","def":"إنَّ هدف التربية الأساس هو أن تجعل المتربي إنساناً ناضجاً حرّاً مسؤولاً، وأهلاً لاتخاذ القرارات.","pg":8},{"term":"الأب الحازم","def":"يريد تحقيق الانضباط لكنه واقعي فيما يتوقعه.","pg":42},{"term":"الأسرة النابذة","def":"وهي الأسرة التي يكون فيها الابن منبوذاً وغير مرغوب فيه من الأب أو من كليهما","pg":46},{"term":"الحب غير المشروط","def":"الحب غير المشروط ضروري لنضج شخصية الأبناء. فنحن نحب أبناءنا لأنهم أولادنا سواء أكانوا ناجحين أم فاشلين، متميزين أم عاديين","pg":68},{"term":"الطاعة الإيجابية","def":"الطاعة لا تعني الموافقة على طول الخط، أو عدم الرد أو المناقشة عند تلقي الأوامر. بل الطاعة تكون نتيجة الحب.","pg":69},{"term":"التكرار في الإنصات","def":"إن التكرار يعني إعادة ما قاله الآخر ومشاعره المرفقة بطريقتي الخاصة وأستخدام مفرداتي الخاصة.","pg":115},{"term":"الاختيار","def":"الاختيار هو اتخاذ قرار أو موقف يلتزم به الإنسان.","pg":138},{"term":"الحرية","def":"القدرة دون إجبار من أحد على اتخاذ قرار ما باستخدام ما هو متاح من معلومات للاختيار بين بدائل تحقق هدفاً محدداً.","pg":143},{"term":"المسؤولية","def":"الاستعداد لتحمّل كامل النتائج المترتبة أو التي ستترتب على ذلك الاختيار (أي اتخاذ ذلك القرار).","pg":144},{"term":"الاستماع بالتقمص العاطفي","def":"إن الاستماع بهدف الوصول إلى داخل عقل وقلب الآخر يُدعى الاستماع بالتقمص العاطفي","pg":148},{"term":"التغذية الراجعة","def":"المقصود من التغذية الراجعة هو تزويد الآخرين بالمعلومات والتوقعات الكافية حول سلوكك وموقفك وقراراتك بوضوح وصراحة قدر المستطاع.","pg":157},{"term":"التكاتف","def":"التكاتف هو أن اثنين أو أكثر من أعضاء العائلة ... يتعاونون ليحصلوا على نتائج أفضل من أن يعمل كل على حدة.","pg":158},{"term":"العصف الذهني","def":"العصف الذهني أحد الطرائق المهمة في توليد الأفكار، وخلاصة هذه الطريقة تعتمد على أن يذكر كل شخص من المجموعة ما يرد عليه من أفكار حول المشكلة مهما كانت قيمتها","pg":165},{"term":"القيم","def":"القيم: معايير عقلية ووجدانية، تستند إلى مرجعية حضارية، تمكن صاحبها من الاختيار بإرادة حرة واعية، وبصورة متكررة نشاطاً إنسانياً.","pg":181},{"term":"عقلية الاستحقاق","def":"الطفل الذي تتم حمايته وتدليله وتعويده على الحصول على كل ما يريد؛ ينشأ على (عقلية الاستحقاق) ويضع نفسه ورغباته قبل كل شيء","pg":182}],"links":[{"topic":"العقوبة","pg":15},{"topic":"الحوار","pg":62},{"topic":"الحب غير المشروط","pg":68},{"topic":"المسؤولية","pg":73},{"topic":"الصراخ","pg":93},{"topic":"الكذب","pg":98},{"topic":"المقارنة بين الأبناء","pg":99},{"topic":"التلفاز","pg":103},{"topic":"الإنصات","pg":110},{"topic":"احترام الذات","pg":189}]};
